const grpc = require('@grpc/grpc-js');
const { SecretVault } = require('../vault');
const { authenticateClientCert } = require('../tls-auth');

async function rotateVaultSecret(call, callback) {
  const authClient = authenticateClientCert(call.getPeerCertificate());
  if (!authClient) {
    return callback({ code: grpc.status.PERMISSION_DENIED, message: 'mTLS verification failed' });
  }

  const { secretKeyId, newCipherPayload } = call.request;
  const vaultRecord = await SecretVault.findOne({ keyId: secretKeyId });
  if (!vaultRecord) {
    return callback({ code: grpc.status.NOT_FOUND, message: 'Secret key not found' });
  }
  if (vaultRecord.tenantId !== authClient.tenantId) {
    return callback({ code: grpc.status.PERMISSION_DENIED, message: 'Access denied to target vault secret' });
  }

  vaultRecord.cipherPayload = newCipherPayload;
  vaultRecord.rotatedAt = new Date();
  await vaultRecord.save();

  return callback(null, { status: 'ROTATED', keyId: secretKeyId });
}
